<ul >{"\n                    "}<li >{"\n                        AWS Control Tower とは(動作の仕組み):\n                        "}<a href={"https://docs.aws.amazon.com/controltower/latest/userguide/how-control-tower-works.html"}>{"https://docs.aws.amazon.com/controltower/latest/userguide/how-control-tower-works.html"}</a>{"\n                    "}</li>{"\n                    "}<li >{"\n                        ランディングゾーンのカスタマイズ:\n                        "}<a href={"https://docs.aws.amazon.com/controltower/latest/userguide/console-customize.html"}>{"https://docs.aws.amazon.com/controltower/latest/userguide/console-customize.html"}</a>{"\n                    "}</li>{"\n                    "}<li >{"\n                        コントロールによるリソース統制(Prescriptive Guidance):\n                        "}<a href={"https://docs.aws.amazon.com/prescriptive-guidance/latest/designing-control-tower-landing-zone/controls.html"}>{"https://docs.aws.amazon.com/prescriptive-guidance/latest/designing-control-tower-landing-zone/controls.html"}</a>{"\n                    "}</li>{"\n                    "}<li >{"\n                        AWS Control Tower の機能:\n                        "}<a href={"https://aws.amazon.com/controltower/features"}>{"https://aws.amazon.com/controltower/features"}</a>{"\n                    "}</li>{"\n                "}</ul>
